/* ocean-calm - shadcn/ui theme (Tailwind v4).
   Drop into your global CSS after `@import "tailwindcss";`.
   Values are the identity spec from identity.json. */

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-ok: var(--ok);
  --color-ok-soft: var(--ok-soft);
  --color-ok-foreground: var(--ok-foreground);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-warn-foreground: var(--warn-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --font-display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

:root,
[data-theme="ocean-calm"] {
  --background: oklch(98.5% 0.005 240);
  --foreground: oklch(26% 0.02 255);
  --card: oklch(100% 0 0);
  --card-foreground: oklch(26% 0.02 255);
  --popover: oklch(100% 0 0);
  --popover-foreground: oklch(26% 0.02 255);
  --primary: oklch(52% 0.2 258);
  --primary-foreground: oklch(99% 0.005 258);
  --secondary: oklch(94% 0.03 250);
  --secondary-foreground: oklch(30% 0.05 258);
  --muted: oklch(96.5% 0.008 242);
  --muted-foreground: oklch(46% 0.02 252);
  --accent: oklch(94% 0.03 250);
  --accent-foreground: oklch(35% 0.1 258);
  --destructive: oklch(52% 0.17 30);
  --destructive-foreground: oklch(99% 0.005 30);
  --ok: oklch(46% 0.11 155);
  --ok-soft: oklch(95% 0.03 155);
  --ok-foreground: oklch(38% 0.09 155);
  --warn: oklch(55% 0.14 65);
  --warn-soft: oklch(96% 0.045 80);
  --warn-foreground: oklch(38% 0.07 65);
  --border: oklch(91% 0.012 242);
  --input: oklch(91% 0.012 242);
  --ring: oklch(52% 0.2 258);
  --radius: 0.625rem;
  --font-display: "Plus Jakarta Sans", "Inter", system-ui, sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;
  --shadow-identity: 0 1px 1px oklch(26% 0.02 255 / 0.05), 0 2px 6px oklch(26% 0.02 255 / 0.05),
    0 12px 32px oklch(52% 0.2 258 / 0.06);
  --identity-gradient-to: oklch(33% 0.1 264);
  color-scheme: light;
}

/* Identity signatures: display face on headings, tabular numbers, calm motion. */
h1, h2, h3, .font-display {
  font-family: var(--font-display);
  letter-spacing: -0.02em;
}
h1 { letter-spacing: -0.03em; }
.tabular { font-variant-numeric: tabular-nums; }
body {
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}


/* ---- overrides ---- */
/* ocean-calm overrides - the opinionated treatment on top of stock shadcn.
   Layer AFTER shadcn styles. Each rule is a deliberate identity decision. */

/* Buttons carry the identity weight and signature shadow. Primary detection:
   shadcn emits no data-variant attribute, so style the slot and let .bg-primary
   (theme-driven) carry the accent shadow. */
[data-identity="ocean-calm"] [data-slot="button"] {
  font-weight: 600;
}
[data-identity="ocean-calm"] [data-slot="button"].bg-primary {
  box-shadow: 0 2px 8px oklch(52% 0.2 258 / 0.3);
}
[data-identity="ocean-calm"] [data-slot="button"]:hover {
  transform: translateY(-1px);
}
[data-identity="ocean-calm"] [data-slot="button"] {
  transition: transform 180ms cubic-bezier(0.22, 0.61, 0.36, 1),
    box-shadow 180ms cubic-bezier(0.22, 0.61, 0.36, 1);
}

/* Cards: one radius everywhere, identity shadow, gentle hover lift. */
[data-identity="ocean-calm"] [data-slot="card"] {
  border-radius: 12px;
  box-shadow: 0 1px 1px oklch(26% 0.02 255 / 0.05), 0 10px 30px oklch(26% 0.02 255 / 0.05);
  transition: transform 220ms cubic-bezier(0.22, 0.61, 0.36, 1),
    box-shadow 220ms cubic-bezier(0.22, 0.61, 0.36, 1);
}
[data-identity="ocean-calm"] a[data-slot="card"]:hover,
[data-identity="ocean-calm"] .hover-lift:hover {
  transform: translateY(-3px);
  box-shadow: 0 1px 2px oklch(26% 0.02 255 / 0.05), 0 6px 16px oklch(26% 0.02 255 / 0.07),
    0 16px 40px oklch(52% 0.2 258 / 0.08);
}

/* Focus: soft azure halo, never a harsh ring. Radius untouched so pills and
   rounded elements keep their shape. */
[data-identity="ocean-calm"] :focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px oklch(94% 0.03 250), 0 0 0 5px oklch(52% 0.2 258 / 0.55);
}

/* Tables: airy, tabular numbers, quiet header. */
[data-identity="ocean-calm"] table {
  font-variant-numeric: tabular-nums;
  border-collapse: separate;
  border-spacing: 0;
}
[data-identity="ocean-calm"] th {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(46% 0.02 252);
}

/* Badges: uppercase tracking, quiet confidence. */
[data-identity="ocean-calm"] [data-slot="badge"] {
  letter-spacing: 0.05em;
  font-weight: 700;
}

/* Inputs: soft focus in the accent halo instead of a hard border color flip. */
[data-identity="ocean-calm"] input,
[data-identity="ocean-calm"] textarea,
[data-identity="ocean-calm"] select {
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

import type { ReactNode } from "react"
import { Card } from "@/components/ui/card"

export function Article({
  eyebrow,
  title,
  meta,
  children,
}: {
  eyebrow: string
  title: string
  meta: string
  children: ReactNode
}) {
  return (
    <article className="mx-auto max-w-[720px] px-6 py-14">
      <span className="text-[11.5px] font-extrabold uppercase tracking-[0.16em] text-primary">
        {eyebrow}
      </span>
      <h1 className="mt-3 font-display text-[34px] font-extrabold leading-[1.12] tracking-[-0.03em]">
        {title}
      </h1>
      <p className="mt-3 text-[13.5px] text-muted-foreground">{meta}</p>
      <div className="mt-9 flex flex-col gap-5 text-[16px] leading-[1.7] [&_blockquote]:border-l-4 [&_blockquote]:border-primary/40 [&_blockquote]:pl-4 [&_blockquote]:italic [&_h2]:mt-10 [&_h2]:font-display [&_h2]:text-[22px] [&_h2]:font-bold [&_h2]:tracking-[-0.02em] [&_li]:mt-2 [&_ul]:ml-5 [&_ul]:list-disc">
        {children}
      </div>
    </article>
  )
}

export function Callout({ tone = "info", children }: { tone?: "info" | "warn"; children: ReactNode }) {
  return (
    <Card
      className={
        tone === "warn"
          ? "rounded-[14px] border-none bg-warn-soft p-4 text-[13.5px] leading-relaxed text-warn-foreground"
          : "rounded-[14px] border-none bg-accent p-4 text-[13.5px] leading-relaxed"
      }
    >
      {children}
    </Card>
  )
}

export function Kpi({ value, label }: { value: string; label: string }) {
  return (
    <Card className="px-5 py-4">
      <b className="font-display text-[24px] font-bold tracking-[-0.02em] tabular-nums">{value}</b>
      <span className="mt-0.5 block text-[12.5px] text-muted-foreground">{label}</span>
    </Card>
  )
}

import type { ReactNode } from "react"
import { Badge } from "@/components/ui/badge"
import { Card, CardContent } from "@/components/ui/card"

export function DashboardShell({
  title,
  nav,
  actions,
  stats,
  children,
}: {
  title: string
  nav: { label: string; active?: boolean; count?: number }[]
  actions?: ReactNode
  stats: { value: string; label: string }[]
  children: ReactNode
}) {
  return (
    <div className="min-h-screen">
      <header className="sticky top-0 z-40 border-b border-border/80 bg-card/85 backdrop-blur-md">
        <div className="mx-auto flex h-[60px] max-w-[1120px] items-center gap-6 px-6">
          <span className="font-display text-[19px] font-extrabold tracking-[-0.02em]">
            {title}
          </span>
          <nav className="ml-auto flex items-center gap-6">
            {nav.map((n) => (
              <a
                key={n.label}
                href="#"
                className={`text-sm font-medium transition-colors ${
                  n.active ? "font-semibold text-foreground" : "text-muted-foreground hover:text-primary"
                }`}
              >
                {n.label}
                {n.count ? ` (${n.count})` : ""}
              </a>
            ))}
          </nav>
          {actions && <div className="flex items-center gap-3">{actions}</div>}
        </div>
      </header>

      <main className="mx-auto max-w-[1120px] px-6 py-10">
        <div className="mb-8 grid grid-cols-2 gap-3.5 lg:grid-cols-4">
          {stats.map((s) => (
            <Card key={s.label} className="rounded-xl px-5 py-4">
              <b className="font-display text-[26px] font-bold tracking-[-0.02em] tabular-nums">{s.value}</b>
              <span className="mt-0.5 block text-[11.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
                {s.label}
              </span>
            </Card>
          ))}
        </div>
        {children}
      </main>
    </div>
  )
}

export function StatBadge({ label, tone = "muted" }: { label: string; tone?: "muted" | "ok" | "warn" | "danger" }) {
  const tones = {
    muted: "bg-secondary text-secondary-foreground",
    ok: "bg-ok-soft text-ok-foreground",
    warn: "bg-warn-soft text-warn-foreground",
    danger: "bg-destructive/10 text-destructive",
  }
  return <Badge className={`rounded-md px-2.5 py-0.5 text-[11px] font-bold uppercase tracking-wide ${tones[tone]}`}>{label}</Badge>
}
